1	package poller
2	
3	import (
4		"encoding/json"
5		"log"
6		"sync"
7		"time"
8	
9		"github.com/itsmaleen/cmux-companion/bridge/internal/socket"
10	)
11	
12	// Notification mirrors the fields we care about from cmux's notification object.
13	type Notification struct {
14		ID          string `json:"id"`
15		Title       string `json:"title"`
16		Subtitle    string `json:"subtitle"`
17		Body        string `json:"body"`
18		WorkspaceID string `json:"workspace_id"`
19		SurfaceID   string `json:"surface_id"`
20		IsRead      bool   `json:"is_read"`
21	}
22	
23	// Event is emitted by the poller to subscribers.
24	// Data is any so that non-notification events (cmux.connected, cmux.disconnected)
25	// can also be broadcast through the same channel.
26	type Event struct {
27		Type string
28		Data any
29	}
30	
31	// Poller polls notification.list on an interval and broadcasts new events.
32	type Poller struct {
33		client   *socket.Client
34		interval time.Duration
35	
36		mu          sync.Mutex
37		subscribers []chan Event
38		seenIDs     map[string]struct{}
39	}
40	
41	func New(client *socket.Client, interval time.Duration) *Poller {
42		return &Poller{
43			client:   client,
44			interval: interval,
45			seenIDs:  make(map[string]struct{}),
46		}
47	}
48	
49	// Subscribe returns a buffered channel that receives events.
50	// Slow consumers drop events rather than blocking the poller.
51	func (p *Poller) Subscribe() <-chan Event {
52		ch := make(chan Event, 32)
53		p.mu.Lock()
54		p.subscribers = append(p.subscribers, ch)
55		p.mu.Unlock()
56		return ch
57	}
58	
59	// Unsubscribe removes a subscriber. The channel is NOT closed — closing a
60	// channel that the poller might concurrently be sending to causes a panic.
61	// The WS handler detects disconnection via other signals (ctx, incoming closed).
62	func (p *Poller) Unsubscribe(ch <-chan Event) {
63		p.mu.Lock()
64		defer p.mu.Unlock()
65		for i, sub := range p.subscribers {
66			if sub == ch {
67				p.subscribers = append(p.subscribers[:i], p.subscribers[i+1:]...)
68				return
69			}
70		}
71	}
72	
73	// Broadcast sends an event to all current subscribers directly.
74	// Used to push cmux connection state changes.
75	func (p *Poller) Broadcast(ev Event) {
76		p.mu.Lock()
77		subs := make([]chan Event, len(p.subscribers))
78		copy(subs, p.subscribers)
79		p.mu.Unlock()
80	
81		for _, sub := range subs {
